<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $action=$_POST['action']??'update'; if($action==='clear'){unset($_SESSION['cart']);} else {foreach(($_POST['qty']??[]) as $id=>$qty){$id=(int)$id;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min(10,$qty);}} flash('success','Shporta u përditësua.'); redirect('cart.php'); }
$items=[];$total=0;$cart=$_SESSION['cart']??[];
if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',array_fill(0,count($ids),'?'));$stmt=$db->prepare("SELECT * FROM products WHERE id IN ($in) AND is_active=1");$types=str_repeat('i',count($ids));$stmt->bind_param($types,...$ids);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$row['qty']=$cart[$row['id']];$row['subtotal']=$row['price']*$row['qty'];$total+=$row['subtotal'];$items[]=$row;}}
$pageTitle='Shporta'; require __DIR__.'/includes/header.php';
?>
<section class="cart-section"><div class="container"><p class="eyebrow">Porosia juaj</p><h1>Shporta <span class="muted">(<?= cart_count() ?>)</span></h1><?php if(!$items): ?><div class="empty-state"><h2>Shporta është bosh.</h2><p class="muted">Produktet që zgjedh do të shfaqen këtu.</p><a class="button button-dark" href="products.php">Fillo blerjen</a></div><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="cart-layout"><div class="table-wrap"><table class="data-table"><thead><tr><th>Produkti</th><th>Çmimi</th><th>Sasia</th><th>Nëntotali</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><div class="cart-product"><img src="<?= e(product_image($item['image'])) ?>" alt=""><div><strong><?= e($item['name']) ?></strong><br><a class="muted" href="product.php?id=<?= $item['id'] ?>">Shiko produktin</a></div></div></td><td><?= money((float)$item['price']) ?></td><td><input style="width:75px" type="number" min="0" max="10" name="qty[<?= $item['id'] ?>]" value="<?= $item['qty'] ?>"></td><td><strong><?= money((float)$item['subtotal']) ?></strong></td></tr><?php endforeach; ?></tbody></table><br><button class="button button-soft" name="action" value="update">Përditëso shportën</button> <button class="button button-danger" name="action" value="clear">Zbraz shportën</button></div><aside class="summary-card"><h3>Përmbledhja</h3><div class="summary-row"><span>Nëntotali</span><strong><?= money($total) ?></strong></div><div class="summary-row"><span>Transporti</span><strong><?= $total>=100?'Falas':money(3) ?></strong></div><div class="summary-row summary-total"><span>Totali</span><span><?= money($total+($total>=100?0:3)) ?></span></div><a class="button button-dark" style="width:100%;margin-top:20px" href="checkout.php">Vazhdo te porosia →</a></aside></div></form><?php endif; ?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
